        0 4px 16px rgba(0, 0, 0, 0.04),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);

    /* Interaction */
    cursor: pointer;
    text-decoration: none;
    color: inherit;

    /* Transitions */
    transition:
        transform var(--ec-transition),
        box-shadow var(--ec-transition),
        border-color var(--ec-transition);

    will-change: transform;
