        background-color var(--ec-transition-fast),
        transform var(--ec-transition-fast),
        box-shadow var(--ec-transition-fast);
}

.entity-card__btn--primary {
    background: linear-gradient(135deg, var(--ec-accent), rgba(var(--ec-accent-rgb), 0.8));
    color: #fff;
}

.entity-card__btn--primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(var(--ec-accent-rgb), 0.35);
}

.entity-card__btn--secondary {
    background: rgba(var(--ec-accent-rgb), 0.1);
    color: var(--ec-accent);
    border: 1px solid rgba(var(--ec-accent-rgb), 0.25);
}

.entity-card__btn--secondary:hover {
    background: rgba(var(--ec-accent-rgb), 0.2);
}

.entity-card__btn:focus-visible {
    outline: 2px solid var(--ec-accent);
    outline-offset: 2px;
}

/* ============================================================================
   LOADING SKELETON STATE
   ============================================================================ */

.entity-card--loading {
    pointer-events: none;
}

.skeleton-shimmer {
    background: linear-gradient(
        90deg,
        rgba(var(--color-border-rgb, 42, 47, 74), 0.3) 0%,
        rgba(var(--color-border-rgb, 42, 47, 74), 0.5) 50%,
        rgba(var(--color-border-rgb, 42, 47, 74), 0.3) 100%
    );
    background-size: 200% 100%;
    animation: skeleton-shimmer 1.5s ease-in-out infinite;
    border-radius: var(--ec-border-radius-inner);
}

@keyframes skeleton-shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

.entity-card--loading .entity-card__icon {
    width: var(--ec-icon-size);
    height: var(--ec-icon-size);
}

.entity-card__title-skeleton {
    height: 1.3rem;
    width: 70%;
    margin-top: 0.25rem;
}

.entity-card__desc-skeleton {
    height: 0.875rem;
    width: 100%;
}

.entity-card__desc-skeleton--short {
    width: 60%;
}

.entity-card__badge-skeleton {
    height: 1.25rem;
    width: 4rem;
    border-radius: 9999px;
}

/* ============================================================================
   WHISPER (Atmospheric Quote)
   ============================================================================ */

.entity-card__whisper {
    margin-top: 0.5rem;
    padding: 0.5rem;
    background: rgba(var(--ec-accent-rgb), 0.05);
    border-left: 2px solid rgba(var(--ec-accent-rgb), 0.3);
    border-radius: 0 var(--ec-border-radius-inner) var(--ec-border-radius-inner) 0;
}

.entity-card__whisper-text {
    display: block;
    font-style: italic;
    font-size: 0.75rem;
    color: var(--color-text-secondary, #9ca3af);
    line-height: 1.5;
}

.entity-card__whisper-source {
    display: block;
    margin-top: 0.25rem;
    font-size: 0.65rem;
    color: rgba(var(--ec-accent-rgb), 0.7);
}

/* ============================================================================
   METADATA SECTION
   ============================================================================ */

.entity-card__metadata {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-size: 0.75rem;
    color: var(--color-text-secondary, #9ca3af);
}

.entity-card__metadata-item {
    padding: 0.25rem 0.5rem;
    background: rgba(var(--color-surface-rgb, 26, 31, 58), 0.5);
    border-radius: var(--ec-border-radius-inner);
}

.entity-card__metadata-item strong {
    color: var(--color-text-primary, #e5e7eb);
}

/* ============================================================================
   AUTHOR BADGE
   ============================================================================ */

.entity-card__author {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.7rem;
    color: var(--color-text-tertiary, #6b7280);
}

.entity-card__author-label {
    opacity: 0.7;
}

.entity-card__author-name {
    color: var(--ec-accent);
}

/* ============================================================================
   MINI CARD VARIANT
   ============================================================================ */

.entity-card--mini .entity-card__mini-link {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    color: inherit;
    text-decoration: none;
    transition: color var(--ec-transition-fast);
}

.entity-card--mini .entity-card__mini-link:hover {
    color: var(--ec-accent);
}

.entity-card--mini .entity-card__mini-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1.25rem;
    height: 1.25rem;
    font-size: 0.875rem;
}

.entity-card--mini .entity-card__mini-name {
    font-size: 0.875rem;
    font-weight: 500;
}

/* ============================================================================
   FULL CARD VARIANT
   ============================================================================ */

.entity-card--full {
    max-width: 800px;
    margin: 0 auto;
}

.entity-card__hero {
    padding: 2rem;
    text-align: center;
    color: #fff;
}

.entity-card__hero-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--ec-icon-size-lg);
    height: var(--ec-icon-size-lg);
    margin-bottom: 1rem;
    font-size: 2.5rem;
}

.entity-card__hero-title {
    margin: 0 0 0.5rem;
    font-family: 'Cinzel', Georgia, serif;
    font-size: 1.75rem;
    font-weight: 700;
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.entity-card__hero-original {
    margin-bottom: 0.5rem;
    font-size: 1rem;
    opacity: 0.8;
}

.entity-card__hero-subtitle {
    margin: 0;
    font-size: 1rem;
    opacity: 0.9;
    max-width: 600px;
    margin: 0 auto;
}

.entity-card__body {
    padding: 1.5rem;
}

.entity-card__section {
    margin-bottom: 1.5rem;
}

.entity-card__section:last-child {
    margin-bottom: 0;
}

.entity-card__section-title {
    margin: 0 0 0.75rem;
    font-family: 'Cinzel', Georgia, serif;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--ec-accent);
    padding-bottom: 0.5rem;
    border-bottom: 1px solid rgba(var(--ec-accent-rgb), 0.2);
}

.entity-card__section-content {
    font-size: 0.9rem;
    line-height: 1.7;
    color: var(--color-text-secondary, #9ca3af);
}

.entity-card__section-content p {
    margin: 0 0 1rem;
}

.entity-card__section-content p:last-child {
    margin-bottom: 0;
}

/* Property Grid */
.entity-card__property-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 1rem;
}

.entity-card__property {
    padding: 0.75rem;
    background: rgba(var(--color-surface-rgb, 26, 31, 58), 0.5);
    border-radius: var(--ec-border-radius-inner);
    border-left: 3px solid var(--ec-accent);
}

.entity-card__property-label {
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-text-tertiary, #6b7280);
    margin-bottom: 0.25rem;
}

.entity-card__property-value {
    font-size: 0.9rem;
    color: var(--color-text-primary, #e5e7eb);
}

/* Tags */
.entity-card__tags-section {
    margin-top: 1rem;
}

.entity-card__tags-title {
    margin: 0 0 0.5rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-text-secondary, #9ca3af);
}

.entity-card__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
}

.entity-card__tag {
    padding: 0.25rem 0.625rem;
    font-size: 0.75rem;
    background: rgba(var(--ec-accent-rgb), 0.1);
    border: 1px solid rgba(var(--ec-accent-rgb), 0.25);
    border-radius: 9999px;
    color: var(--ec-accent);
}

/* Related Entities */
.entity-card__related-category {
    margin-bottom: 1rem;
}

.entity-card__related-title {
    margin: 0 0 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--color-text-secondary, #9ca3af);
}

.entity-card__related-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.entity-card__mini-entity {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    padding: 0.375rem 0.625rem;
    background: rgba(var(--color-surface-rgb, 26, 31, 58), 0.5);
    border: 1px solid rgba(var(--ec-accent-rgb), 0.2);
    border-radius: var(--ec-border-radius-inner);
    text-decoration: none;
    color: var(--color-text-primary, #e5e7eb);
    font-size: 0.8rem;
    transition: border-color var(--ec-transition-fast), background var(--ec-transition-fast);
}

.entity-card__mini-entity:hover {
    border-color: var(--ec-accent);
    background: rgba(var(--ec-accent-rgb), 0.1);
}

.entity-card__mini-entity-icon {
    width: 1.25rem;
    height: 1.25rem;
    font-size: 0.875rem;
}

/* Sources */
.entity-card__sources-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.entity-card__source {
    padding: 0.5rem 0;
    border-bottom: 1px solid rgba(var(--color-border-rgb, 42, 47, 74), 0.3);
    font-size: 0.85rem;
    color: var(--color-text-secondary, #9ca3af);
}

.entity-card__source:last-child {
    border-bottom: none;
}

.entity-card__source-link {
    margin-left: 0.5rem;
    color: var(--ec-accent);
    text-decoration: none;
}

.entity-card__source-link:hover {
    text-decoration: underline;
}

/* Archetypes */
.entity-card__archetypes-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 1rem;
}

.entity-card__archetype {
    padding: 1rem;
    background: rgba(var(--color-surface-rgb, 26, 31, 58), 0.5);
    border-radius: var(--ec-border-radius-inner);
}

.entity-card__archetype-name {
    margin: 0 0 0.5rem;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--color-text-primary, #e5e7eb);
}

.entity-card__archetype-score {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
}

.entity-card__score-bar {
    flex: 1;
    height: 6px;
    background: rgba(var(--color-border-rgb, 42, 47, 74), 0.5);
    border-radius: 3px;
    overflow: hidden;
}

.entity-card__score-fill {
    height: 100%;
    background: var(--ec-accent);
    border-radius: 3px;
    transition: width 0.5s ease;
}

.entity-card__score-value {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--ec-accent);
    min-width: 2.5rem;
    text-align: right;
}

.entity-card__archetype-context {
    margin: 0;
    font-size: 0.8rem;
    color: var(--color-text-secondary, #9ca3af);
    line-height: 1.5;
}

/* ============================================================================
   ERROR STATE
   ============================================================================ */

.entity-card--error {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 2rem;
    text-align: center;
    border-color: rgba(239, 68, 68, 0.3);
    background: rgba(239, 68, 68, 0.05);
}

.entity-card__error-icon {
    width: 3rem;
    height: 3rem;
    margin-bottom: 1rem;
    color: #ef4444;
}

.entity-card__error-icon svg {
    width: 100%;
    height: 100%;
}

.entity-card__error-title {
    margin: 0 0 0.5rem;
    font-size: 1rem;
    font-weight: 600;
    color: var(--color-text-primary, #e5e7eb);
}

.entity-card__error-id {
    margin: 0 0 0.25rem;
    font-size: 0.8rem;
    font-family: monospace;
    color: var(--color-text-secondary, #9ca3af);
}

.entity-card__error-detail {
    margin: 0;
    font-size: 0.75rem;
    color: #ef4444;
}

/* ============================================================================
   PERSPECTIVES INDICATOR
   ============================================================================ */

.entity-card__perspectives {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.7rem;
    color: var(--color-text-tertiary, #6b7280);
}

.entity-card__perspectives .perspectives-icon {
    width: 1rem;
    height: 1rem;
}

/* ============================================================================
   ACCESSIBILITY - HIGH CONTRAST MODE
   ============================================================================ */

@media (prefers-contrast: high) {
    .entity-card {
        border-width: 2px;
        border-color: var(--ec-accent);
    }

    .entity-card__pill {
        border-width: 2px;
        font-weight: 700;
    }

    .entity-card:focus,
    .entity-card:focus-visible {
        outline-width: 4px;
        outline-offset: 4px;
    }

    .entity-card__action-btn:focus-visible {
        outline-width: 3px;
    }
}

/* ============================================================================
   ACCESSIBILITY - REDUCED MOTION
   ============================================================================ */

@media (prefers-reduced-motion: reduce) {
    .entity-card,
    .entity-card__image,
    .entity-card__icon,
    .entity-card__quick-actions,
    .entity-card__action-btn,
    .entity-card__pill,
    .entity-card__btn,
    .entity-card__title-link {
        transition: none !important;
    }

    .entity-card:hover {
        transform: none;
    }

    .entity-card:hover .entity-card__image {
        transform: none;
    }

    .skeleton-shimmer,
    .entity-card__image-skeleton {
        animation: none;
        opacity: 0.5;
    }

    .entity-card__action-btn--loading .entity-card__action-icon {
        animation: none;
    }
}

/* ============================================================================
   RESPONSIVE - TABLET
   ============================================================================ */

@media (max-width: 900px) {
    :root {
        --ec-min-height: 300px;
        --ec-icon-size: 2.25rem;
        --ec-action-size: 2rem;
    }

    .entity-card__title {
        font-size: 1rem;
    }

    .entity-card__description {
        font-size: 0.8rem;
        -webkit-line-clamp: 2;
    }
}

/* ============================================================================
   RESPONSIVE - MOBILE
   ============================================================================ */

@media (max-width: 600px) {
    :root {
        --ec-min-height: 260px;
        --ec-content-padding: 0.75rem;
        --ec-icon-size: 2rem;
        --ec-title-lines: 2;
        --ec-desc-lines: 2;
    }

    .entity-card__title {
        font-size: 0.95rem;
    }

    .entity-card__description {
        font-size: 0.8rem;
    }

    .entity-card__pill {
        font-size: 0.6rem;
        padding: 0.15rem 0.4rem;
    }

    .entity-card__btn {
        font-size: 0.75rem;
        padding: 0.4rem 0.75rem;
    }

    /* Always show quick actions on mobile (no hover) */
    .entity-card__quick-actions {
        opacity: 1;
        transform: translateX(0);
    }

    /* Full card adjustments */
    .entity-card__hero {
        padding: 1.5rem 1rem;
    }

    .entity-card__hero-title {
        font-size: 1.4rem;
    }

    .entity-card__body {
        padding: 1rem;
    }

    .entity-card__property-grid {
        grid-template-columns: 1fr;
    }
}

/* ============================================================================
   TOUCH DEVICE OPTIMIZATIONS
   ============================================================================ */

@media (hover: none) and (pointer: coarse) {
    .entity-card:hover {
        transform: none;
    }

    .entity-card:hover .entity-card__image {
        transform: none;
    }

    .entity-card:active {
        transform: scale(0.98);
        opacity: 0.95;
    }

    /* Always show quick actions on touch devices */
    .entity-card__quick-actions {
        opacity: 1;
        transform: translateX(0);
    }

    .entity-card__action-btn {
        /* 44px minimum touch target per WCAG 2.5.5 */
        width: 2.75rem;
        height: 2.75rem;
        min-width: 44px;
        min-height: 44px;
    }

    .entity-card__btn {
        /* Minimum touch target height */
        min-height: 44px;
        padding: 0.5rem 1rem;
    }
}

/* ============================================================================
   PRINT STYLES
   ============================================================================ */

@media print {
    .entity-card {
        break-inside: avoid;
        page-break-inside: avoid;
        border: 1px solid #ccc;
        background: #fff;
        color: #000;
        box-shadow: none;
        backdrop-filter: none;
    }

    .entity-card__quick-actions,
    .entity-card__footer {
        display: none;
    }

    .entity-card__image-wrapper {
        background: #f0f0f0;
    }

    .entity-card__title-link {
        color: #000;
    }

    .entity-card__pill {
        border-color: #ccc;
        background: #f5f5f5;
        color: #333;
    }
}

/* ============================================================================
   STAGGERED ANIMATION ON LOAD
   ============================================================================ */

@keyframes cardFadeIn {
    from {
        opacity: 0;
        transform: translateY(16px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.entity-grid > .entity-card {
    animation: cardFadeIn 0.35s ease-out backwards;
}

.entity-grid > .entity-card:nth-child(1) { animation-delay: 0.05s; }
.entity-grid > .entity-card:nth-child(2) { animation-delay: 0.1s; }
.entity-grid > .entity-card:nth-child(3) { animation-delay: 0.15s; }
.entity-grid > .entity-card:nth-child(4) { animation-delay: 0.2s; }
.entity-grid > .entity-card:nth-child(5) { animation-delay: 0.25s; }
.entity-grid > .entity-card:nth-child(6) { animation-delay: 0.3s; }
.entity-grid > .entity-card:nth-child(7) { animation-delay: 0.35s; }
.entity-grid > .entity-card:nth-child(8) { animation-delay: 0.4s; }
.entity-grid > .entity-card:nth-child(n+9) { animation-delay: 0.45s; }

/* Disable stagger on mobile for performance */
@media (max-width: 768px) {
    .entity-grid > .entity-card {
        animation-delay: 0s !important;
    }
}

/* ============================================================================
   LEGACY CLASS COMPATIBILITY
   Maintains backward compatibility with older class names
   ============================================================================ */

/* Map old classes to new BEM structure */
.entity-card .entity-icon-large,
.entity-card .card-icon {
    width: var(--ec-icon-size);
    height: var(--ec-icon-size);
    display: flex;
    align-items: center;
    justify-content: center;
}

.entity-card .card-title {
    font-family: 'Cinzel', 'Cormorant Garamond', Georgia, serif;
    font-size: 1.1rem;
    font-weight: 600;
    line-height: 1.3;
    display: -webkit-box;
    -webkit-line-clamp: var(--ec-title-lines);
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.entity-card .card-description,
.entity-card .entity-short-desc {
    font-size: 0.875rem;
    line-height: 1.55;
    color: var(--color-text-secondary, #9ca3af);
    display: -webkit-box;
    -webkit-line-clamp: var(--ec-desc-lines);
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.entity-card .entity-type-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.2rem 0.5rem;
    font-size: 0.65rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-radius: 9999px;
    background: rgba(var(--ec-type-color, var(--color-primary)), 0.15);
    border: 1px solid rgba(var(--ec-type-color, var(--color-primary)), 0.35);
    color: var(--ec-type-color, var(--color-primary));
}

.entity-card .mythology-badge {
    display: inline-flex;
    align-items: center;
    padding: 0.2rem 0.5rem;
    font-size: 0.65rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-radius: 9999px;
    background: rgba(var(--ec-accent-rgb), 0.15);
    border: 1px solid rgba(var(--ec-accent-rgb), 0.35);
    color: var(--ec-accent);
}

.entity-card .btn-view-details {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.5rem 1rem;
    font-size: 0.8rem;
    font-weight: 600;
    text-decoration: none;
    border: none;
    border-radius: var(--ec-border-radius-inner);
    background: linear-gradient(135deg, var(--ec-accent), rgba(var(--ec-accent-rgb), 0.8));
    color: #fff;
    cursor: pointer;
    transition: transform var(--ec-transition-fast), box-shadow var(--ec-transition-fast);
}

.entity-card .btn-view-details:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(var(--ec-accent-rgb), 0.35);
}

.entity-card .entity-favorite {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    padding: 0;
    border: none;
    border-radius: 50%;
    background: rgba(var(--ec-accent-rgb), 0.1);
    color: var(--ec-accent);
    cursor: pointer;
    transition: background-color var(--ec-transition-fast), transform var(--ec-transition-fast);
}

.entity-card .entity-favorite:hover {
    background: rgba(var(--ec-accent-rgb), 0.2);
    transform: scale(1.1);
}

.entity-card .entity-favorite.favorited {
    background: #ff6b6b;
    color: #fff;
}

/* ============================================================================
   CARD TRUNCATION RULES (merged from card-truncation.css)
   Strict text truncation for grid/array/card displays.
   Full panel/page displays show full content (no truncation).
   ============================================================================ */

/* --- Truncation Design Tokens --- */

:root {
    /* Line clamp values */
    --card-title-max-lines: 2;
    --card-desc-max-lines: 3;
    --card-desc-compact-lines: 2;
    --card-desc-mobile-lines: 2;

    /* Card height constraints */
    --card-strict-min-height: 280px;
    --card-strict-max-height: 380px;
    --card-strict-height-xs: 200px;
    --card-strict-height-sm: 240px;
    --card-strict-height-md: 320px;
    --card-strict-height-lg: 400px;

    /* Typography for truncation */
    --card-title-font-size: 1.1rem;
    --card-title-line-height: 1.35;
    --card-desc-font-size: 0.875rem;
    --card-desc-line-height: 1.55;
}

/* --- Title Truncation - Max 2 Lines --- */

.card-title-truncate,
.entity-grid .card-title,
.entity-grid .entity-card__title,
.entity-grid .grid-card-title,
.universal-grid .card-title,
.universal-grid .grid-card-title,
.browse-category-grid .card-title,
[data-display-mode="grid"] .card-title {
    /* CSS line-clamp for exactly 2 lines */
    display: -webkit-box;
    -webkit-line-clamp: var(--card-title-max-lines, 2);
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;

    /* Consistent typography */
    font-size: var(--card-title-font-size, 1.1rem);
    line-height: var(--card-title-line-height, 1.35);

    /* Height constraint based on line count */
    max-height: calc(var(--card-title-max-lines, 2) * var(--card-title-font-size, 1.1rem) * var(--card-title-line-height, 1.35));

    /* Prevent word breaks in middle of words */
    word-break: break-word;
    overflow-wrap: break-word;
    hyphens: auto;

    /* Text rendering */
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
}

/* Title truncation specifically in card contexts */
.entity-card .card-title,
.entity-card .entity-card__title,
.grid-card .grid-card-title {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    max-height: 3em; /* ~2 lines */
}

/* --- Description Truncation - Max 3 Lines --- */

.card-desc-truncate,
.entity-grid .card-description,
.entity-grid .entity-card__description,
.entity-grid .grid-card-description,
.entity-grid .entity-short-desc,
.universal-grid .card-description,
.universal-grid .grid-card-description,
.browse-category-grid .card-description,
[data-display-mode="grid"] .card-description {
    /* CSS line-clamp for exactly 3 lines */
    display: -webkit-box;
    -webkit-line-clamp: var(--card-desc-max-lines, 3);
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;

    /* Consistent typography */
    font-size: var(--card-desc-font-size, 0.875rem);
    line-height: var(--card-desc-line-height, 1.55);

    /* Height constraint based on line count */
    max-height: calc(var(--card-desc-max-lines, 3) * var(--card-desc-font-size, 0.875rem) * var(--card-desc-line-height, 1.55));

    /* Prevent word breaks in middle of words */
    word-break: break-word;
    overflow-wrap: break-word;

    /* Secondary text color */
    color: var(--color-text-secondary, #9ca3af);

    /* Text rendering */
    -webkit-font-smoothing: antialiased;
}

/* Description truncation specifically in card contexts */
.entity-card .card-description,
.entity-card .entity-card__description,
.entity-card .entity-short-desc,
.grid-card .grid-card-description {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    max-height: 4.65em; /* ~3 lines at 1.55 line-height */
}

/* --- Strict Height Constraints for Cards --- */

.card-strict-height,
.entity-grid > .entity-card,
.entity-grid > .grid-card,
.universal-grid > .entity-card,
.universal-grid > .grid-card,
.universal-grid > .universal-grid-card,
[data-display-mode="grid"] > .entity-card {
    /* Strict height bounds */
    min-height: var(--card-strict-min-height, 280px);
    max-height: var(--card-strict-max-height, 380px);

    /* Ensure content doesn't overflow */
    overflow: hidden;

    /* Flex layout for proper content distribution */
    display: flex;
    flex-direction: column;
}

/* Card content area - flex grow to fill available space */
.card-strict-height .entity-card__content,
.card-strict-height .grid-card-body,
.entity-grid > .entity-card .entity-card__content,
.entity-grid > .grid-card .grid-card-body,
.universal-grid > .entity-card .entity-card__content,
.universal-grid > .grid-card .grid-card-body {
    flex: 1;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

/* Card footer - fixed at bottom */
.card-strict-height .entity-card__footer,
.card-strict-height .grid-card-footer,
.entity-grid > .entity-card .entity-card__footer,
.entity-grid > .grid-card .grid-card-footer,
.universal-grid > .entity-card .entity-card__footer,
.universal-grid > .grid-card .grid-card-footer {
    margin-top: auto;
    flex-shrink: 0;
}

/* --- Size Variants - Different Card Sizes --- */

/* Extra Small Cards */
.card-strict-height--xs,
.entity-grid--ultra-compact > .entity-card,
.entity-grid--ultra-compact > .grid-card,
[data-density="ultra-compact"] > .entity-card {
    min-height: var(--card-strict-height-xs, 200px);
    max-height: 260px;
    --card-desc-max-lines: 2;
}

/* Small/Compact Cards */
.card-strict-height--sm,
.entity-grid--compact > .entity-card,
.entity-grid--compact > .grid-card,
[data-density="compact"] > .entity-card {
    min-height: var(--card-strict-height-sm, 240px);
    max-height: 300px;
    --card-desc-max-lines: 2;
}

/* Medium Cards (default) */
.card-strict-height--md,
.entity-grid--comfortable > .entity-card,
.entity-grid--comfortable > .grid-card,
[data-density="comfortable"] > .entity-card {
    min-height: var(--card-strict-height-md, 320px);
    max-height: 400px;
    --card-desc-max-lines: 3;
}

/* Large/Detailed Cards */
.card-strict-height--lg,
.entity-grid--detailed > .entity-card,
.entity-grid--detailed > .grid-card,
[data-density="detailed"] > .entity-card {
    min-height: var(--card-strict-height-lg, 400px);
    max-height: 500px;
    --card-desc-max-lines: 4;
}

/* --- Compact Truncation - 2 Lines for Description --- */

.card-desc-truncate--compact,
.entity-grid--compact .card-description,
.entity-grid--compact .entity-card__description,
.entity-grid--compact .grid-card-description,
[data-density="compact"] .card-description,
[data-density="ultra-compact"] .card-description {
    -webkit-line-clamp: var(--card-desc-compact-lines, 2);
    max-height: calc(var(--card-desc-compact-lines, 2) * var(--card-desc-font-size, 0.875rem) * var(--card-desc-line-height, 1.55));
}

/* --- Array/List Displays - Apply Same Truncation --- */

/* List items in array/list views */
.universal-list .list-item-title,
.entity-list .list-item-title,
[data-display-mode="list"] .list-item-title {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
}

.universal-list .list-item-description,
.entity-list .list-item-description,
[data-display-mode="list"] .list-item-description {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* --- Table Displays - Truncation for Cell Content --- */

.universal-table td,
.entity-table td,
[data-display-mode="table"] td {
    max-width: 250px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* Name cells can wrap but limited */
.universal-table .name-cell,
.entity-table .name-cell {
    max-width: 200px;
    white-space: normal;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

/* --- Inline Displays - Single Line Truncation --- */

.entity-inline,
.inline-entity-link,
[data-display-mode="inline"] .entity-name {
    display: inline-block;
    max-width: 150px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    vertical-align: middle;
}

/* --- Full Panel/Page Displays - NO TRUNCATION --- */

/* Panel display mode - show full content */
.entity-panel .panel-title,
.entity-panel .entity-card__hero-title,
.entity-card--full .entity-card__hero-title,
[data-display-mode="panel"] .panel-title,
.universal-panel-card .panel-title {
    /* Remove line clamp - show full title */
    display: block;
    -webkit-line-clamp: unset;
    -webkit-box-orient: unset;
    overflow: visible;
    text-overflow: unset;
    max-height: none;
}

/* Panel description - show full content */
.entity-panel .panel-description,
.entity-panel .panel-content,
.entity-panel .section-content,
.entity-card--full .entity-card__section-content,
.entity-card--full .entity-card__description,
[data-display-mode="panel"] .panel-description,
.universal-panel-card .panel-description,
.universal-panel-card .panel-content {
    /* Remove line clamp - show full description */
    display: block;
    -webkit-line-clamp: unset;
    -webkit-box-orient: unset;
    overflow: visible;
    text-overflow: unset;
    max-height: none;
}

/* Full card variant - no truncation */
.entity-card--full,
.entity-card--full .entity-card__content,
.entity-card--full .entity-card__body {
    max-height: none;
    overflow: visible;
}

/* Entity detail pages - full content */
.entity-detail .entity-title,
.entity-detail .entity-description,
.entity-detail-page .entity-title,
.entity-detail-page .entity-description,
.entity-page .entity-title,
.entity-page .entity-description {
    display: block;
    -webkit-line-clamp: unset;
    -webkit-box-orient: unset;
    overflow: visible;
    text-overflow: unset;
    max-height: none;
}

/* Section content in detail views - full text */
.entity-detail .section-content,
.entity-detail-page .section-content,
.panel-section .section-content,
.text-section .section-content {
    display: block;
    -webkit-line-clamp: unset;
    -webkit-box-orient: unset;
    overflow: visible;
    max-height: none;
}

/* --- Truncatable Text with Show More (Panel Views) --- */

/* Text that can be expanded */
.truncatable-text {
    position: relative;
}

.truncatable-text .truncatable-content {
    display: -webkit-box;
    -webkit-line-clamp: var(--max-lines, 3);
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.truncatable-text.truncate-expanded .truncatable-content {
    display: block;
    -webkit-line-clamp: unset;
    -webkit-box-orient: unset;
    overflow: visible;
}

.truncatable-text .truncate-toggle {
    display: inline-block;
    margin-top: 0.5rem;
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    color: var(--color-primary, #8b7fff);
    background: transparent;
    border: 1px solid rgba(var(--color-primary-rgb, 139, 127, 255), 0.3);
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.truncatable-text .truncate-toggle:hover {
    background: rgba(var(--color-primary-rgb, 139, 127, 255), 0.1);
    border-color: var(--color-primary, #8b7fff);
}

.truncatable-text .truncate-toggle .toggle-more {
    display: inline;
}

.truncatable-text .truncate-toggle .toggle-less {
    display: none;
}

.truncatable-text.truncate-expanded .truncate-toggle .toggle-more {
    display: none;
}

.truncatable-text.truncate-expanded .truncate-toggle .toggle-less {
    display: inline;
}

/* --- Pills/Tags Truncation - Limit Visible Pills --- */

.pills-container {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
}

.pills-container .pills-visible {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
}

.pills-container .pills-hidden {
    display: none;
    flex-wrap: wrap;
    gap: 0.375rem;
}

.pills-container.pills-expanded .pills-hidden {
    display: flex;
    margin-top: 0.375rem;
}

.pills-container .pill-more,
.pills-container .pill-less {
    cursor: pointer;
    background: rgba(var(--color-primary-rgb, 139, 127, 255), 0.15);
    color: var(--color-primary, #8b7fff);
    border: 1px dashed rgba(var(--color-primary-rgb, 139, 127, 255), 0.4);
}

.pills-container .pill-more:hover,
.pills-container .pill-less:hover {
    background: rgba(var(--color-primary-rgb, 139, 127, 255), 0.25);
}

/* --- Metadata Truncation - Limit Long Values --- */

.entity-card__metadata-item,
.metadata-item,
.field-value {
    max-width: 200px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* Allow wrapping in panel views */
.entity-panel .metadata-item,
.entity-panel .field-value,
[data-display-mode="panel"] .metadata-item,
[data-display-mode="panel"] .field-value {
    max-width: none;
    white-space: normal;
    overflow: visible;
}

/* --- Responsive Truncation - Mobile Optimizations --- */

/* Tablet - reduce to 2 lines for description */
@media (max-width: 900px) {
    .entity-grid .card-description,
    .entity-grid .entity-card__description,
    .universal-grid .grid-card-description {
        -webkit-line-clamp: 2;
        max-height: calc(2 * var(--card-desc-font-size, 0.875rem) * var(--card-desc-line-height, 1.55));
    }

    .card-strict-height,
    .entity-grid > .entity-card,
    .universal-grid > .entity-card {
        min-height: 260px;
        max-height: 340px;
    }
}

/* Mobile Portrait - aggressive truncation */
@media (max-width: 600px) {
    :root {
        --card-title-max-lines: 2;
        --card-desc-max-lines: 2;
        --card-strict-min-height: 220px;
        --card-strict-max-height: 300px;
    }

    .entity-grid .card-title,
    .entity-grid .entity-card__title,
    .universal-grid .grid-card-title {
        font-size: 0.95rem;
        -webkit-line-clamp: 2;
    }

    .entity-grid .card-description,
    .entity-grid .entity-card__description,
    .universal-grid .grid-card-description {
        font-size: 0.8rem;
        -webkit-line-clamp: 2;
        max-height: 2.8em;
    }

    .card-strict-height,
    .entity-grid > .entity-card,
    .universal-grid > .entity-card {
        min-height: var(--card-strict-min-height);
        max-height: var(--card-strict-max-height);
    }
}

/* Small Mobile - minimal content */
@media (max-width: 480px) {
    .entity-grid .card-description,
    .entity-grid .entity-card__description,
    .universal-grid .grid-card-description {
        -webkit-line-clamp: 2;
        font-size: 0.75rem;
    }

    .entity-grid .card-title,
    .entity-grid .entity-card__title,
    .universal-grid .grid-card-title {
        font-size: 0.875rem;
    }

    /* Hide metadata on very small screens */
    .entity-grid .entity-card__metadata,
    .entity-grid .grid-card-meta {
        display: none;
    }

    /* Reduce card min-height on small mobile screens (320px-480px) */
    .card-strict-height,
    .entity-grid > .entity-card,
    .universal-grid > .entity-card,
    .entity-grid--compact > .grid-card,
    [data-density="compact"] > .entity-card {
        min-height: auto;
    }
}

/* --- Accessibility - Truncated Content Still Accessible --- */

/* Provide full text via aria-label on truncated elements */
[aria-label].card-title-truncate,
[aria-label].card-desc-truncate {
    /* Screen readers will read aria-label instead of truncated visible text */
}

/* High contrast mode - clearer truncation indicator */
@media (prefers-contrast: high) {
    .card-title-truncate,
    .card-desc-truncate {
        /* Use stronger ellipsis visual */
        text-decoration-style: dotted;
    }

    .truncatable-text .truncate-toggle {
        border-width: 2px;
        font-weight: 600;
    }
}

/* Reduced motion - no transitions on truncation interactions */
@media (prefers-reduced-motion: reduce) {
    .truncatable-text .truncate-toggle,
    .pills-container .pill-more,
    .pills-container .pill-less {
        transition: none;
    }
}

/* --- Print Styles - Full Content for Print --- */

@media print {
    /* Remove all truncation for print */
    .card-title-truncate,
    .card-desc-truncate,
    .entity-grid .card-title,
    .entity-grid .card-description,
    .entity-grid .entity-card__title,
    .entity-grid .entity-card__description,
    .universal-grid .grid-card-title,
    .universal-grid .grid-card-description {
        display: block;
        -webkit-line-clamp: unset;
        -webkit-box-orient: unset;
        overflow: visible;
        text-overflow: unset;
        max-height: none;
    }

    /* Show all hidden pills */
    .pills-container .pills-hidden {
        display: flex !important;
    }

    .pills-container .pill-more,
    .pills-container .pill-less {
        display: none !important;
    }

    /* Remove height constraints */
    .card-strict-height,
    .entity-grid > .entity-card,
    .universal-grid > .entity-card {
        min-height: auto;
        max-height: none;
    }
}

/* --- Utility Classes - Manual Override --- */

/* Force no truncation */
.no-truncate {
    display: block !important;
    -webkit-line-clamp: unset !important;
    -webkit-box-orient: unset !important;
    overflow: visible !important;
    text-overflow: unset !important;
    max-height: none !important;
}

/* Force 1-line truncation */
.truncate-1-line {
    display: -webkit-box !important;
    -webkit-line-clamp: 1 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}

/* Force 2-line truncation */
.truncate-2-lines {
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}

/* Force 3-line truncation */
.truncate-3-lines {
    display: -webkit-box !important;
    -webkit-line-clamp: 3 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}

/* Force single-line ellipsis (no wrap) */
.truncate-ellipsis {
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
}

