/* hoisted to top of bundle: https://fonts.googleapis.com/css2?family=Inter:wght@300 */400;500;600;700&family=Crimson+Text:ital,wght@0,400;0,600;1,400&display=swap');

/* Entity Card & Grid Polish - Unified styling for all entity cards */
/* inlined: css/entity-card-polish.css */

:root {
    /* Use CSS variables from theme-base.css */
