    --border-primary: var(--color-border-primary, #2a2f4a);
    --border-accent: var(--color-border-accent, #4a4f6a);
    --success: #51cf66;
    --info: #4dabf7;
    --warning: #ffd43b;
    --glass-bg: rgba(var(--color-bg-card-rgb, 26, 31, 58), 0.8);
