/* ============================================
   TEXT READABILITY ENFORCEMENT
   Ensures proper contrast in all themes
   ============================================ */

/* Light themes need dark text */
[data-theme="day"] h1,
[data-theme="day"] h2,
[data-theme="day"] h3,
[data-theme="day"] h4,
[data-theme="day"] h5,
[data-theme="day"] h6,
[data-theme="air"] h1,
[data-theme="air"] h2,
[data-theme="air"] h3,
[data-theme="air"] h4,
[data-theme="air"] h5,
[data-theme="air"] h6,
[data-theme="order"] h1,
[data-theme="order"] h2,
[data-theme="order"] h3,
[data-theme="order"] h4,
[data-theme="order"] h5,
[data-theme="order"] h6,
[data-theme="light"] h1,
[data-theme="light"] h2,
[data-theme="light"] h3,
[data-theme="light"] h4,
[data-theme="light"] h5,
[data-theme="light"] h6 {
    color: var(--color-text-primary, #0f172a);
    text-shadow: none;
}

/* Dark themes get text glow */
[data-theme="night"] h1,
[data-theme="night"] h2,
[data-theme="celestial"] h1,
[data-theme="celestial"] h2,
[data-theme="cosmic"] h1,
[data-theme="cosmic"] h2 {
    text-shadow: 0 0 30px rgba(var(--color-primary-rgb, 139, 127, 255), 0.3);
}

/* Ensure links are readable */
a {
    color: var(--color-primary, #8b7fff);
    transition: color var(--transition-fast, 0.15s ease);
}

a:hover {
    color: var(--color-primary-light, #a99fff);
}

a:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
    border-radius: var(--radius-sm, 0.25rem);
}

/* Light theme link adjustments */
[data-theme="day"] a,
[data-theme="air"] a,
[data-theme="order"] a,
[data-theme="light"] a {
    color: var(--color-primary, #2563eb);
}

[data-theme="day"] a:hover,
[data-theme="air"] a:hover,
[data-theme="order"] a:hover,
[data-theme="light"] a:hover {
    color: var(--color-primary-dark, #1e40af);
}

/* ============================================
   ENHANCED FOCUS STATES
   Accessible focus indicators using theme colors
   ============================================ */

/* Interactive elements get proper focus */
button:focus-visible,
[role="button"]:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
a:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
}

/* Cards and panels get subtle focus */
.card:focus-within,
.glass-card:focus-within,
.entity-card:focus-within {
    box-shadow: var(--focus-ring), var(--shadow-lg, 0 10px 15px -3px rgba(0, 0, 0, 0.2));
    border-color: var(--color-primary, #8b7fff);
}

/* Skip to content link */
.skip-to-content {
    position: absolute;
    top: -100%;
    left: 50%;
    transform: translateX(-50%);
    padding: 1rem 2rem;
    background: var(--color-primary, #8b7fff);
    color: white;
    text-decoration: none;
    border-radius: 0 0 var(--radius-lg, 0.75rem) var(--radius-lg, 0.75rem);
    z-index: var(--z-max, 9999);
    transition: top 0.3s ease;
}

.skip-to-content:focus {
    top: 0;
}

/* Reduced motion: simpler focus styles */
@media (prefers-reduced-motion: reduce) {
    .badge,
    .mythology-badge,
    .category-badge {
        transition: none;
    }

    [data-theme="chaos"] .badge,
    [data-theme="chaos"] .mythology-badge {
        animation: none;
    }
}

