/* ============================================
   THEME PREVIEW STYLING
   For hover preview before applying
   ============================================ */

/* Theme preview active state */
html.theme-preview-active {
    /* Slightly faster transitions during preview */
    transition: all 0.15s ease;
}

html.theme-preview-active *:not(.theme-dropdown):not(.theme-option) {
    transition: background-color 0.15s ease,
                color 0.15s ease,
                border-color 0.15s ease !important;
}

/* Preview indicator overlay */
html.theme-preview-active::after {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg,
        var(--color-primary, #8b7fff),
        var(--color-secondary, #ff7eb6),
        var(--color-primary, #8b7fff));
    background-size: 200% 100%;
    animation: previewIndicator 1s linear infinite;
    z-index: 9999;
    opacity: 0.8;
}

@keyframes previewIndicator {
    0% { background-position: 0% 0%; }
    100% { background-position: 200% 0%; }
}

