/* ==== css/dynamic-views.css ==== */
/**
 * Dynamic Views CSS
 * Styles for the dynamic SPA navigation system
 *
 * Includes:
 * - View transition animations
 * - Loading/error states
 * - Breadcrumb navigation
 * - Component-specific styles
 * - Responsive layouts
 * - Visual polish enhancements
 * - Glassmorphism effects
 * - Parallax integration
 */

/* ============================================
   VIEW CONTAINER
   ============================================ */

.view-container {
    min-height: 60vh;
    position: relative;
}

/* View Transitions */
.view-transition-out {
    opacity: 0;
    transform: translateY(-10px);
    transition: opacity 150ms ease-out, transform 150ms ease-out;
}

.view-transition-in {
    animation: fadeInUp 300ms ease-out;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Loading State */
.view-loading {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 400px;
}

.loading-container {
    text-align: center;
    width: 100%;
}

.loading-message {
    margin-top: var(--spacing-lg, 1.5rem);
    color: var(--color-text-secondary, #9ca3af);
    font-size: var(--font-size-lg, 1.125rem);
}

/* Error State */
.view-error {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 400px;
}

.error-container {
    text-align: center;
    max-width: 600px;
    padding: var(--spacing-xl, 2rem);
}

.error-icon {
    font-size: 4rem;
    margin-bottom: var(--spacing-lg, 1.5rem);
}

.error-container h2 {
    color: var(--color-text-primary, #e5e7eb);
    margin-bottom: var(--spacing-md, 1rem);
}

.error-message {
    color: var(--color-text-secondary, #9ca3af);
    margin-bottom: var(--spacing-xl, 2rem);
    line-height: 1.6;
}

.error-actions {
    display: flex;
    gap: var(--spacing-md, 1rem);
    justify-content: center;
    flex-wrap: wrap;
}

/* Empty State */
.empty-container {
    text-align: center;
    padding: var(--spacing-4xl, 4rem) var(--spacing-xl, 2rem);
}

.empty-icon {
    font-size: 4rem;
    margin-bottom: var(--spacing-lg, 1.5rem);
    opacity: 0.7;
}

.empty-container h2 {
    color: var(--color-text-primary, #e5e7eb);
    margin-bottom: var(--spacing-md, 1rem);
}

.empty-message {
    color: var(--color-text-secondary, #9ca3af);
    margin-bottom: var(--spacing-xl, 2rem);
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.empty-actions {
    display: flex;
    gap: var(--spacing-md, 1rem);
    justify-content: center;
    flex-wrap: wrap;
}

/* ============================================
   BREADCRUMB NAVIGATION
   ============================================ */

#breadcrumb-nav {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(var(--color-bg-card-rgb, 26, 31, 58), 0.95);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 2px solid var(--color-border, rgba(139, 127, 255, 0.3));
    padding: var(--spacing-md, 1rem) 0;
    margin-bottom: var(--spacing-lg, 1.5rem);
    opacity: 0;
    transform: translateY(-100%);
    transition: opacity 300ms ease, transform 300ms ease;
}

#breadcrumb-nav.visible {
    opacity: 1;
    transform: translateY(0);
}

.breadcrumb-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-xl, 2rem);
}

.breadcrumb-list {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    list-style: none;
    margin: 0;
    padding: 0;
    gap: var(--spacing-xs, 0.25rem);
}

.breadcrumb-item {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs, 0.25rem);
}

.breadcrumb-link {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs, 0.25rem);
    color: var(--color-primary, #667eea);
    text-decoration: none;
    padding: var(--spacing-xs, 0.25rem) var(--spacing-sm, 0.5rem);
    border-radius: var(--radius-md, 8px);
    transition: all 150ms ease;
}

.breadcrumb-link:hover {
    background: rgba(102, 126, 234, 0.1);
    color: var(--color-primary-light, #818cf8);
}

.breadcrumb-icon {
    font-size: 1rem;
    line-height: 1;
}

.breadcrumb-label {
    font-size: var(--font-size-sm, 0.875rem);
    font-weight: var(--font-medium, 500);
}

.breadcrumb-separator {
    color: var(--color-text-secondary, #9ca3af);
    margin: 0 var(--spacing-xs, 0.25rem);
    user-select: none;
}

.breadcrumb-current {
    color: var(--color-text-primary, #e5e7eb);
    padding: var(--spacing-xs, 0.25rem) var(--spacing-sm, 0.5rem);
}

/* Mobile breadcrumbs */
@media (max-width: 768px) {
    .breadcrumb-label {
        font-size: var(--font-size-xs, 0.75rem);
    }

    .breadcrumb-link {
        padding: var(--spacing-xs, 0.25rem);
    }
}

