    padding: 0.75rem 1.25rem;
    border-radius: 12px;
}

.reputation-level-display.tier-bronze {
    background: var(--tier-bronze-bg);
}

.reputation-level-display.tier-silver {
    background: var(--tier-silver-bg);
}

.reputation-level-display.tier-gold {
    background: var(--tier-gold-bg);
}

.reputation-level-display.tier-platinum {
    background: var(--tier-platinum-bg);
}

.reputation-level-display .level-icon {
    width: 32px;
    height: 32px;
}

.reputation-level-display .level-icon svg {
    width: 100%;
    height: 100%;
}

.reputation-level-display.tier-bronze .level-icon {
    color: var(--tier-bronze);
}

.reputation-level-display.tier-silver .level-icon {
    color: var(--tier-silver);
}

.reputation-level-display.tier-gold .level-icon {
    color: var(--tier-gold);
}

.reputation-level-display.tier-platinum .level-icon {
    color: var(--tier-platinum);
}

.reputation-level-display .level-name {
    font-size: 1.25rem;
    font-weight: 700;
}

.reputation-level-display.tier-bronze .level-name {
    color: var(--tier-bronze);
}

.reputation-level-display.tier-silver .level-name {
    color: var(--tier-silver);
}

.reputation-level-display.tier-gold .level-name {
    color: var(--tier-gold);
}

.reputation-level-display.tier-platinum .level-name {
    color: var(--tier-platinum);
}

.reputation-points {
    text-align: right;
}

.reputation-points .points-value {
    display: block;
    font-size: 2rem;
    font-weight: 700;
    color: var(--dashboard-text);
    line-height: 1;
}

.reputation-points .points-label {
    font-size: 0.8125rem;
    color: var(--dashboard-text-muted);
}

/* Progress Section */
.reputation-progress-section {
    margin-bottom: 2rem;
}

.progress-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
    font-size: 0.8125rem;
    color: var(--dashboard-text-muted);
}

.reputation-progress-bar {
    height: 10px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 5px;
    overflow: hidden;
}

.progress-fill {
    height: 100%;
    border-radius: 5px;
    transition: width 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
}

.progress-fill::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    animation: shimmer 2s infinite;
}

.progress-fill.tier-bronze {
    background: linear-gradient(90deg, var(--tier-bronze), #b87333);
}

.progress-fill.tier-silver {
    background: linear-gradient(90deg, var(--tier-silver), #a8a8a8);
}

.progress-fill.tier-gold {
    background: linear-gradient(90deg, var(--tier-gold), #f0a500);
}

.progress-fill.tier-platinum {
    background: linear-gradient(90deg, var(--tier-platinum), #a0c4e8);
}

/* Level Roadmap */
.level-roadmap {
    display: flex;
    justify-content: space-between;
    position: relative;
    padding: 1rem 0;
}

.level-roadmap::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 0;
    right: 0;
    height: 2px;
    background: rgba(255, 255, 255, 0.1);
    transform: translateY(-50%);
}

.roadmap-level {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    position: relative;
    z-index: 1;
}

.roadmap-marker {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.1);
    border: 2px solid rgba(255, 255, 255, 0.2);
    transition: all 0.3s ease;
}

.roadmap-level.achieved .roadmap-marker {
    background: var(--dashboard-accent);
    border-color: var(--dashboard-accent);
}

.roadmap-level.current .roadmap-marker {
    transform: scale(1.5);
    box-shadow: 0 0 12px rgba(139, 127, 255, 0.5);
}

.roadmap-level.tier-bronze.achieved .roadmap-marker {
    background: var(--tier-bronze);
    border-color: var(--tier-bronze);
}

.roadmap-level.tier-silver.achieved .roadmap-marker {
    background: var(--tier-silver);
    border-color: var(--tier-silver);
}

.roadmap-level.tier-gold.achieved .roadmap-marker {
    background: var(--tier-gold);
    border-color: var(--tier-gold);
}

.roadmap-level.tier-platinum.achieved .roadmap-marker {
    background: var(--tier-platinum);
    border-color: var(--tier-platinum);
}

.roadmap-name {
    font-size: 0.6875rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    color: var(--dashboard-text-muted);
}

.roadmap-level.achieved .roadmap-name {
    color: var(--dashboard-text);
}

.roadmap-points {
    font-size: 0.625rem;
    color: var(--dashboard-text-muted);
    opacity: 0.7;
}

/* Badges Section */
.badges-section {
    background: var(--dashboard-card-bg);
    border: 1px solid var(--dashboard-border);
    border-radius: 16px;
    padding: 1.5rem;
}

/* Points Breakdown */
.points-breakdown-section {
    background: var(--dashboard-card-bg);
    border: 1px solid var(--dashboard-border);
    border-radius: 16px;
    padding: 1.5rem;
}

.points-table {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.points-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: rgba(255, 255, 255, 0.02);
    border-radius: 8px;
}

.points-action {
    font-size: 0.875rem;
    color: var(--dashboard-text);
}

.points-amount {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--dashboard-accent);
}

/* ==========================================================================
   Settings Tab
   ========================================================================== */

.dashboard-settings {
    display: flex;
    flex-direction: column;
    gap: 2rem;
}

.settings-section {
    background: var(--dashboard-card-bg);
    border: 1px solid var(--dashboard-border);
    border-radius: 16px;
    padding: 1.5rem;
}

.settings-section-title {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    font-size: 1rem;
    font-weight: 600;
    color: var(--dashboard-text);
    margin: 0 0 1.5rem;
}

.settings-section-title svg {
    color: var(--dashboard-accent);
}

.settings-form {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.form-group label {
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--dashboard-text);
}

.form-input,
.form-textarea {
    padding: 0.75rem 1rem;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--dashboard-border);
    border-radius: 10px;
    color: var(--dashboard-text);
    font-size: 0.9375rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.form-input:focus,
.form-textarea:focus {
    outline: none;
    border-color: var(--dashboard-accent);
    box-shadow: 0 0 0 3px rgba(139, 127, 255, 0.1);
}

.form-input::placeholder,
.form-textarea::placeholder {
    color: var(--dashboard-text-muted);
}

.form-textarea {
    resize: vertical;
    min-height: 80px;
}

.form-hint {
    font-size: 0.75rem;
    color: var(--dashboard-text-muted);
}

.char-count {
    text-align: right;
}

/* Avatar Upload */
.avatar-upload {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.avatar-preview {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    overflow: hidden;
    background: var(--dashboard-accent-light);
    border: 2px solid var(--dashboard-border);
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-preview .avatar-initial {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--dashboard-accent);
}

.avatar-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

/* Toggle Switch */
.form-group--toggle {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: rgba(255, 255, 255, 0.02);
    border-radius: 12px;
}

.toggle-content {
    display: flex;
    flex-direction: column;
    gap: 0.125rem;
}

.toggle-label {
    font-size: 0.9375rem;
    font-weight: 500;
    color: var(--dashboard-text);
}

.toggle-description {
    font-size: 0.8125rem;
    color: var(--dashboard-text-muted);
}

.toggle-switch {
    position: relative;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 13px;
    transition: 0.3s ease;
}

.toggle-slider::before {
    content: '';
    position: absolute;
    width: 20px;
    height: 20px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s ease;
}

.toggle-switch input:checked + .toggle-slider {
    background: var(--dashboard-accent);
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(22px);
}

.toggle-switch input:focus + .toggle-slider {
    box-shadow: 0 0 0 3px rgba(139, 127, 255, 0.2);
}

/* Settings Actions */
.settings-actions {
    display: flex;
    justify-content: flex-end;
}

/* ==========================================================================
   Pagination
   ========================================================================== */

.pagination {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--dashboard-border);
}

.pagination-info {
    font-size: 0.9rem;
    color: var(--dashboard-text-muted);
}

.pagination-controls {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.pagination-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    padding: 0;
    background: var(--dashboard-card-bg);
    border: 1px solid var(--dashboard-border);
    border-radius: var(--dashboard-radius-sm);
    color: var(--dashboard-text);
    cursor: pointer;
    transition: var(--dashboard-transition);
}

.pagination-btn svg {
    width: 18px;
    height: 18px;
}

.pagination-btn:hover:not(:disabled) {
    background: var(--dashboard-gold-light);
    border-color: var(--dashboard-gold);
    color: var(--dashboard-gold);
}

.pagination-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.pagination-current {
    font-size: 0.9rem;
    color: var(--dashboard-text);
    min-width: 60px;
    text-align: center;
}

/* ==========================================================================
   Auth Required State
   ========================================================================== */

.dashboard-auth-required {
    max-width: 500px;
    margin: 4rem auto;
    padding: 3rem;
    text-align: center;
}

.auth-icon {
    width: 80px;
    height: 80px;
    margin: 0 auto 1.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--dashboard-gold-light);
    border-radius: 50%;
    color: var(--dashboard-gold);
}

.auth-icon svg {
    width: 40px;
    height: 40px;
}

.dashboard-auth-required h2 {
    margin: 0 0 0.75rem;
    font-size: 1.75rem;
    color: var(--dashboard-gold);
}

.auth-message {
    margin: 0 0 2rem;
    color: var(--dashboard-text-muted);
    line-height: 1.6;
}

/* ==========================================================================
   Modal
   ========================================================================== */

.dashboard-modal {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.8);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 10000;
    padding: 2rem;
}

.dashboard-modal[aria-hidden="false"] {
    display: flex;
}

/* ==========================================================================
   Buttons
   ========================================================================== */

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 10px;
    font-size: 0.875rem;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.2s ease;
    border: none;
}

.btn-sm {
    padding: 0.5rem 1rem;
    font-size: 0.8125rem;
    border-radius: 8px;
}

.btn-icon-svg {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
}

.btn-primary {
    background: var(--dashboard-accent);
    color: white;
}

.btn-primary:hover {
    background: #7a6bea;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(139, 127, 255, 0.3);
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--dashboard-border);
    color: var(--dashboard-text);
}

.btn-secondary:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.2);
}

.btn-ghost {
    background: transparent;
    color: var(--dashboard-text-muted);
}

.btn-ghost:hover {
    background: rgba(255, 255, 255, 0.05);
    color: var(--dashboard-text);
}

.btn-large {
    padding: 1rem 2rem;
    font-size: 1.1rem;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
}

/* Loading Spinner */
.loading-spinner {
    display: inline-block;
    width: 16px;
    height: 16px;
    border: 2px solid rgba(255, 255, 255, 0.2);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* ==========================================================================
   Screen Reader Only
   ========================================================================== */

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* ==========================================================================
   Skeleton Loading
   ========================================================================== */

.skeleton {
    background: linear-gradient(
        90deg,
        var(--dashboard-card-bg) 25%,
        rgba(255, 255, 255, 0.1) 50%,
        var(--dashboard-card-bg) 75%
    );
    background-size: 200% 100%;
    animation: shimmer 1.5s infinite;
    border-radius: var(--dashboard-radius-sm);
}

@keyframes shimmer {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
}

.skeleton-card {
    height: 80px;
    margin-bottom: 1rem;
}

.skeleton-stat {
    height: 100px;
}

/* ==========================================================================
   Responsive Design
   ========================================================================== */

@media (max-width: 1200px) {
    .dashboard-stats {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
    .user-dashboard {
        padding: 1rem;
    }

    .dashboard-header {
        flex-direction: column;
        gap: 1.5rem;
        padding: 1.5rem;
    }

    .dashboard-header__profile {
        flex-direction: column;
        text-align: center;
    }

    .dashboard-header-content {
        flex-direction: column;
        text-align: center;
    }

    .dashboard-user-info {
        text-align: center;
    }

    .dashboard-level-progress {
        max-width: 100%;
    }

    .level-progress-info {
        justify-content: center;
    }

    .dashboard-header__actions {
        width: 100%;
        justify-content: center;
    }

    .dashboard-avatar {
        width: 64px;
        height: 64px;
    }

    .dashboard-welcome {
        font-size: 1.5rem;
    }

    .dashboard-stats {
        grid-template-columns: repeat(2, 1fr);
        gap: 1rem;
    }

    .stat-card {
        padding: 1rem;
    }

    .stat-icon {
        width: 40px;
        height: 40px;
    }

    .stat-value {
        font-size: 1.5rem;
    }

    .dashboard-tabs {
        flex-wrap: nowrap;
        overflow-x: auto;
        scrollbar-width: none;
        -ms-overflow-style: none;
        -webkit-overflow-scrolling: touch;
    }

    .dashboard-tabs::-webkit-scrollbar {
        display: none;
    }

    .dashboard-tab {
        padding: 0.625rem 1rem;
        font-size: 0.8125rem;
    }

    .dashboard-tab span:not(.tab-count) {
        display: none;
    }

    .dashboard-tab-content {
        padding: 1.25rem;
    }

    .submission-card {
        flex-wrap: wrap;
        gap: 0.75rem;
    }

    .submission-icon {
        width: 40px;
        height: 40px;
    }

    .submission-content {
        flex: 1 1 100%;
        order: 2;
    }

    .submission-status {
        order: 1;
    }

    .submission-actions {
        order: 3;
        width: 100%;
        justify-content: flex-end;
    }

    .contribution-item {
        flex-direction: column;
        align-items: stretch;
        gap: 0.75rem;
    }

    .contribution-item__main {
        flex-direction: column;
        align-items: flex-start;
    }

    .contribution-item__status {
        align-self: flex-start;
    }

    .contribution-item__actions {
        justify-content: flex-start;
    }

    .favorites-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .favorites-actions {
        width: 100%;
        flex-wrap: wrap;
    }

    .favorites-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 1rem;
    }

    .favorite-card {
        padding: 1rem;
    }

    .favorite-icon {
        width: 48px;
        height: 48px;
    }

    .reputation-header {
        flex-direction: column;
        gap: 1rem;
        text-align: center;
    }

    .reputation-points {
        text-align: center;
    }

    .level-roadmap {
        flex-wrap: wrap;
        gap: 1rem;
        justify-content: center;
    }

    .roadmap-level {
        width: 60px;
    }

    .settings-section {
        padding: 1.25rem;
    }

    .form-group--toggle {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }

    .pagination {
        flex-direction: column;
        gap: 1rem;
    }
}

@media (max-width: 480px) {
    .dashboard-stats {
        grid-template-columns: 1fr;
    }

    .stat-card {
        padding: 1rem;
    }

    .stat-card__value {
        font-size: 1.5rem;
    }

    .favorites-grid,
    .collections-grid {
        grid-template-columns: 1fr;
    }

    .contribution-breakdown {
        grid-template-columns: 1fr;
    }

    .stat-card-inner {
        justify-content: center;
    }

    .dashboard-tab {
        flex: 1;
        justify-content: center;
    }
}

/* ==========================================================================
   Accessibility
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* Focus Visible */
.btn:focus-visible,
.dashboard-tab:focus-visible,
.action-btn:focus-visible,
.pagination-btn:focus-visible,
.favorite-card:focus-visible,
.submission-card:focus-visible,
.form-input:focus-visible,
.form-textarea:focus-visible,
.toggle-switch input:focus-visible + .toggle-slider {
    outline: 2px solid var(--dashboard-accent);
    outline-offset: 2px;
}

/* High Contrast Support */
@media (prefers-contrast: high) {
    .glass-card {
        border-width: 2px;
    }

    .stat-card::before {
        height: 4px;
    }

    .submission-status {
        border: 1px solid currentColor;
    }
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--dashboard-accent);
    color: white;
    padding: 8px 16px;
    z-index: 100;
    text-decoration: none;
}

.skip-link:focus {
    top: 0;
}

/* ==========================================================================
   Light Theme
   ========================================================================== */

[data-theme="light"] .user-dashboard {
    --dashboard-bg: rgba(247, 250, 252, 0.95);
    --dashboard-card-bg: rgba(0, 0, 0, 0.03);
    --dashboard-border: rgba(0, 0, 0, 0.1);
    --dashboard-text: #2d3748;
    --dashboard-text-muted: #718096;
    --dashboard-gold: #d69e2e;
}

[data-theme="light"] .glass-card {
    background: linear-gradient(135deg, white, #f7fafc);
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
}

[data-theme="light"] .dashboard-tabs {
    background: rgba(0, 0, 0, 0.02);
}

[data-theme="light"] .stat-tooltip {
    background: white;
    border-color: rgba(0, 0, 0, 0.1);
}

[data-theme="light"] .stat-tooltip::after {
    border-top-color: white;
}

[data-theme="light"] .btn-primary {
    box-shadow: 0 4px 12px rgba(214, 158, 46, 0.3);
}

/* ==========================================================================
   Print Styles
   ========================================================================== */

@media print {
    .user-dashboard {
        background: white;
        color: black;
    }

    .dashboard-header__actions,
    .dashboard-tabs,
    .btn,
    .section-link {
        display: none;
    }

    .dashboard-section,
    .settings-section,
    .reputation-card {
        break-inside: avoid;
        page-break-inside: avoid;
    }
}


