    --mythology-gradient: linear-gradient(135deg, rgba(16, 185, 129, 0.08), rgba(251, 191, 36, 0.06));
}

/* Jewish - Blue & White */
[data-mythology="jewish"],
[data-mythology="hebrew"] {
    --mythology-glow: rgba(59, 130, 246, 0.1);
    --mythology-accent: #3b82f6;
    --mythology-secondary: #f8fafc;
    --mythology-border: rgba(59, 130, 246, 0.35);
    --mythology-gradient: linear-gradient(135deg, rgba(59, 130, 246, 0.08), rgba(248, 250, 252, 0.05));
}

/* Universal/Tarot - Mystical Purple */
[data-mythology="tarot"],
[data-mythology="universal"],
[data-mythology="hermetic"] {
